import catalogJson from "./qwen-voice-catalog.json";

// Generated by scripts/gen-qwen-voice-catalog.mjs from the official Qwen-Audio-TTS voice list.
type PageVoice = { id: string; name: string; gender?: string; trait?: string; lang?: string; scene?: string; preview: string };
type BasicVoice = { slug: string; name: string; gender?: string; age?: number; trait?: string; scene?: string; lang?: string };
type Catalog = { source: string; fetchedAt: string; models: Record<string, Array<{ group: string; voices: PageVoice[] }>>; basic: { models: string[]; voices: BasicVoice[] } };

export type QwenVoiceOption = { value: string; label: string; group: string; preview: string; search: string };

const catalog = catalogJson as Catalog;

export const QWEN_VOICE_PREVIEW_ROUTE = "/api/public/qwen-voice-previews";
export const QWEN_BASIC_VOICE_GROUP = "基础音色";
export const qwenCatalogModels = Object.keys(catalog.models);

const basicPreviewFiles = new Set(catalog.basic.voices.map((voice) => `${voice.slug}.wav`));

export function isQwenBasicPreviewFile(file: string) {
    return basicPreviewFiles.has(file);
}

export function qwenCatalogVoices(model: string): QwenVoiceOption[] {
    const groups = catalog.models[model];
    if (!groups) return [];
    const voices = groups.flatMap(({ group, voices: items }) =>
        items.map((voice) => {
            const detail = voice.lang && !voice.trait && group.includes("小语种") ? [voice.lang, voice.gender] : [voice.gender, voice.trait];
            return option(voice.id, voice.name, detail, group, voice.preview, [voice.trait, voice.lang, voice.scene]);
        }),
    );
    if (!catalog.basic.models.includes(model)) return voices;
    return [...voices, ...catalog.basic.voices.map((voice) => option(`${model}-${voice.slug}`, voice.name, [voice.gender, voice.trait], QWEN_BASIC_VOICE_GROUP, `${QWEN_VOICE_PREVIEW_ROUTE}/${voice.slug}.wav`, [voice.scene, voice.lang, voice.slug]))];
}

function option(value: string, name: string, detail: Array<string | undefined>, group: string, preview: string, extra: Array<string | undefined>): QwenVoiceOption {
    const suffix = detail.filter(Boolean).join("·");
    const label = suffix ? `${name}（${suffix}）` : name;
    return { value, label, group, preview, search: [label, value, ...extra].filter(Boolean).join(" ").toLowerCase() };
}
